-- =====================================================================
-- 0369 — Custom Forms: the three Daven Hodge agreements.
--
-- Adds three internal, published Custom Forms for US In Home Services
-- (HR Paperworks → Custom Forms), text as provided 2026-10-09:
--   * Information Security & System Quarantine Agreement
--   * Conditional Continuation of Employment & Last Chance Agreement (LCA)
--   * Sworn Affidavit of Daven Hodge
-- Daven signs and dates his part on the form's link; the Authorized
-- Representative (agreements) and the notary (affidavit) fields are
-- "Filled in by: Company", completed by HR from Submissions → Complete.
--
-- Adds rows only — nothing existing is changed. Skips any form whose title
-- already exists, so it's safe to run twice.
-- Run once in the Supabase SQL Editor, after 0368.
-- =====================================================================

insert into hr_custom_forms (company_id, title, description, access, status, fields, created_by)
select 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd', 'Information Security & System Quarantine Agreement', 'For Daven Hodge. Read the agreement, then sign and date it at the bottom. The company''s Authorized Representative signs after you submit.', 'internal', 'published', '[{"id":"fdhmv15txbj0","name":"title","type":"heading","label":"","style":{},"width":100,"config":{"text":"INFORMATION SECURITY & SYSTEM QUARANTINE AGREEMENT","level":3,"bold":true,"alignment":"center"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbj1","name":"agreement_text","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>This Information Security &amp; System Quarantine Agreement (\"Agreement\") is entered into on October 9, 2026, by and between US In Home Services LLC (\"Company\") and Daven Hodge (\"Employee\").</p><p><strong>PURPOSE &amp; AUDIT:</strong> Employee acknowledges that the Company is conducting a comprehensive internal security audit regarding company databases, BPO operational assets, and trade secret protections.</p><p><strong>SYSTEM QUARANTINE &amp; ACCESS LIMITATIONS:</strong></p><p>a. Employee agrees to the immediate quarantine, modification, or revocation of administrative and master database privileges as designated by executive management.</p><p>b. Employee shall strictly access company systems, B2B portals, and communications solely within explicitly authorized boundaries.</p><p><strong>PROHIBITION OF DATA EXFILTRATION OR SPOLIATION:</strong></p><p>a. Employee shall NOT copy, transfer, screenshot, download, or transmit any company data, spreadsheets, client records, or system credentials to any external device or third party.</p><p>b. Employee shall NOT delete, alter, wipe, or destroy any electronic files, logs, emails, text messages, or database entries. Any spoliation of evidence will result in immediate legal action.</p><p><strong>ACKNOWLEDGMENT OF PROPRIETARY OWNERSHIP:</strong> Employee confirms that all master data, BPO assets, dispatch logs, and operational workflows remain the exclusive intellectual property and trade secrets of the Company.</p><p>IN WITNESS WHEREOF, the parties have executed this Agreement as of October 9, 2026.</p>","text":"This Information Security & System Quarantine Agreement (\"Agreement\") is entered into on October 9, 2026, by and between US In Home Services LLC (\"Company\") and Daven Hodge (\"Employee\").\n\nPURPOSE & AUDIT: Employee acknowledges that the Company is conducting a comprehensive internal security audit regarding company databases, BPO operational assets, and trade secret protections.\n\nSYSTEM QUARANTINE & ACCESS LIMITATIONS:\n\na. Employee agrees to the immediate quarantine, modification, or revocation of administrative and master database privileges as designated by executive management.\n\nb. Employee shall strictly access company systems, B2B portals, and communications solely within explicitly authorized boundaries.\n\nPROHIBITION OF DATA EXFILTRATION OR SPOLIATION:\n\na. Employee shall NOT copy, transfer, screenshot, download, or transmit any company data, spreadsheets, client records, or system credentials to any external device or third party.\n\nb. Employee shall NOT delete, alter, wipe, or destroy any electronic files, logs, emails, text messages, or database entries. Any spoliation of evidence will result in immediate legal action.\n\nACKNOWLEDGMENT OF PROPRIETARY OWNERSHIP: Employee confirms that all master data, BPO assets, dispatch logs, and operational workflows remain the exclusive intellectual property and trade secrets of the Company.\n\nIN WITNESS WHEREOF, the parties have executed this Agreement as of October 9, 2026.","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbj2","name":"employee_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"EMPLOYEE","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbj3","name":"employee_signature","type":"signature","label":"Daven Hodge (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbj4","name":"employee_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbj5","name":"employee_name","type":"shortText","label":"Employee Printed Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Daven Hodge"},{"id":"fdhmv15txbj6","name":"company_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"US IN HOME SERVICES LLC","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbj7","name":"rep_signature","type":"signature","label":"Authorized Representative (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbj8","name":"rep_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbj9","name":"rep_name_title","type":"shortText","label":"Authorized Representative Name / Title","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"}]'::jsonb, '78d3504c-56f9-43a0-b7b1-091e3eba7d36'
where exists (select 1 from companies where id = 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd')
  and not exists (select 1 from hr_custom_forms where company_id = 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd' and title = 'Information Security & System Quarantine Agreement');

insert into hr_custom_forms (company_id, title, description, access, status, fields, created_by)
select 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd', 'Conditional Continuation of Employment & Last Chance Agreement (LCA)', 'For Daven Hodge. Read the agreement, then sign and date it at the bottom. The company''s Authorized Representative signs after you submit.', 'internal', 'published', '[{"id":"fdhmv15txbja","name":"title","type":"heading","label":"","style":{},"width":100,"config":{"text":"CONDITIONAL CONTINUATION OF EMPLOYMENT & LAST CHANCE AGREEMENT (LCA)","level":3,"bold":true,"alignment":"center"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjb","name":"agreement_text","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>This Agreement is made on October 9, 2026, by and between US In Home Services LLC (\"Company\") and Daven Hodge (\"Employee\").</p><p><strong>RECITALS:</strong></p><p>WHEREAS, the Company is investigating unauthorized data access, trade secret misappropriation, and operational interference involving former personnel and Apex / Sycamore; and</p><p>WHEREAS, the Company agrees to conditionally continue Employee’s employment under the terms set forth below;</p><p>NOW, THEREFORE, the parties agree as follows:</p><p><strong>MANDATORY LITIGATION &amp; INVESTIGATION COOPERATION:</strong></p><p>a. As a strict condition of continued employment, Employee agrees to provide full, truthful, and complete cooperation with executive management and legal counsel regarding all internal investigations, audits, depositions, and legal proceedings against Apex / Sycamore and associated individuals.</p><p>b. Employee shall promptly disclose all relevant communications, records, and information pertaining to any outreach or solicitation by former employees or Apex personnel.</p><p><strong>FULL COMPLIANCE WITH COMPANY POLICIES:</strong> Employee agrees to strictly comply with all company security protocols, non-disclosure obligations, and executive directives. Any insubordination or failure to adhere to security mandates shall constitute immediate cause for termination.</p><p><strong>CONSEQUENCES OF BREACH:</strong> Failure to fully comply with any term of this Agreement will result in immediate termination of employment for cause, without prior notice, and may subject Employee to civil litigation for breach of contract and co-liability.</p><p><strong>VOLUNTARY EXECUTION &amp; ACKNOWLEDGMENT:</strong> Employee acknowledges that this Agreement is executed voluntarily, without duress or coercion. Employee confirms having received adequate time to review this Agreement and understands that employment remains at-will except as modified by the specific compliance obligations herein.</p><p>IN WITNESS WHEREOF, the parties have signed this Agreement as of October 9, 2026.</p>","text":"This Agreement is made on October 9, 2026, by and between US In Home Services LLC (\"Company\") and Daven Hodge (\"Employee\").\n\nRECITALS:\n\nWHEREAS, the Company is investigating unauthorized data access, trade secret misappropriation, and operational interference involving former personnel and Apex / Sycamore; and\n\nWHEREAS, the Company agrees to conditionally continue Employee’s employment under the terms set forth below;\n\nNOW, THEREFORE, the parties agree as follows:\n\nMANDATORY LITIGATION & INVESTIGATION COOPERATION:\n\na. As a strict condition of continued employment, Employee agrees to provide full, truthful, and complete cooperation with executive management and legal counsel regarding all internal investigations, audits, depositions, and legal proceedings against Apex / Sycamore and associated individuals.\n\nb. Employee shall promptly disclose all relevant communications, records, and information pertaining to any outreach or solicitation by former employees or Apex personnel.\n\nFULL COMPLIANCE WITH COMPANY POLICIES: Employee agrees to strictly comply with all company security protocols, non-disclosure obligations, and executive directives. Any insubordination or failure to adhere to security mandates shall constitute immediate cause for termination.\n\nCONSEQUENCES OF BREACH: Failure to fully comply with any term of this Agreement will result in immediate termination of employment for cause, without prior notice, and may subject Employee to civil litigation for breach of contract and co-liability.\n\nVOLUNTARY EXECUTION & ACKNOWLEDGMENT: Employee acknowledges that this Agreement is executed voluntarily, without duress or coercion. Employee confirms having received adequate time to review this Agreement and understands that employment remains at-will except as modified by the specific compliance obligations herein.\n\nIN WITNESS WHEREOF, the parties have signed this Agreement as of October 9, 2026.","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjc","name":"employee_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"EMPLOYEE","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjd","name":"employee_signature","type":"signature","label":"Daven Hodge (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbje","name":"employee_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjf","name":"employee_name","type":"shortText","label":"Employee Printed Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Daven Hodge"},{"id":"fdhmv15txbjg","name":"company_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"US IN HOME SERVICES LLC","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjh","name":"rep_signature","type":"signature","label":"Authorized Representative (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbji","name":"rep_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjj","name":"rep_name_title","type":"shortText","label":"Authorized Representative Name / Title","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"}]'::jsonb, '78d3504c-56f9-43a0-b7b1-091e3eba7d36'
where exists (select 1 from companies where id = 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd')
