insert into hr_custom_forms (company_id, title, description, access, status, fields, created_by)
select 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd', 'Sworn Affidavit of Daven Hodge', 'For Daven Hodge. Read the affidavit, then sign and date it at the bottom. The notary acknowledgment is completed by the company afterwards.', 'internal', 'published', '[{"id":"fdhmv15txbjk","name":"title","type":"heading","label":"","style":{},"width":100,"config":{"text":"SWORN AFFIDAVIT OF DAVEN HODGE","level":3,"bold":true,"alignment":"center"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjl","name":"affidavit_text","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>STATE OF TENNESSEE )<br>COUNTY OF SHELBY )</p><p>I, Daven Hodge, being first duly sworn, depose and state under penalty of perjury as follows:</p><p>I am currently employed by US In Home Services LLC (“Company”) as Lead Administrator / IT System Manager.</p><p>During my employment, I became aware of coordinated actions taken by former employees, including but not limited to Garrett, Aleena, Justin Parker, Jon Allen, Joe Gallagher, and entities associated with Apex / Sycamore (“Apex Group”).</p><p>I personally witnessed and have knowledge that members of the Apex Group systematically exfiltrated and misappropriated proprietary company assets, including B2B partner spreadsheets, customer dispatch databases, technician scheduling data, pricing/cost structures, and operational Standard Operating Procedures (SOPs).</p><p>I confirm that members of the Apex Group actively solicited active company technicians, administrative staff, and BPO personnel to breach their obligations to the Company and transition clients, warranty work orders, and trade secrets to Apex while still employed or under contractual obligations with the Company.</p><p>I further acknowledge that certain former employees intentionally delayed, misdiagnosed, or diverted active repair jobs and B2B warranty tickets (including Hisense and SquareTrade) away from the Company to artificially inflate Apex’s volume and harm the Company’s operational metrics.</p><p>All statements made in this Affidavit are true, correct, and based on my direct personal knowledge and observations. I execute this document voluntarily and without any coercion.</p><p>IN WITNESS WHEREOF, I have executed this Affidavit on this ____ day of October, 2026.</p>","text":"STATE OF TENNESSEE )\nCOUNTY OF SHELBY )\n\nI, Daven Hodge, being first duly sworn, depose and state under penalty of perjury as follows:\n\nI am currently employed by US In Home Services LLC (“Company”) as Lead Administrator / IT System Manager.\n\nDuring my employment, I became aware of coordinated actions taken by former employees, including but not limited to Garrett, Aleena, Justin Parker, Jon Allen, Joe Gallagher, and entities associated with Apex / Sycamore (“Apex Group”).\n\nI personally witnessed and have knowledge that members of the Apex Group systematically exfiltrated and misappropriated proprietary company assets, including B2B partner spreadsheets, customer dispatch databases, technician scheduling data, pricing/cost structures, and operational Standard Operating Procedures (SOPs).\n\nI confirm that members of the Apex Group actively solicited active company technicians, administrative staff, and BPO personnel to breach their obligations to the Company and transition clients, warranty work orders, and trade secrets to Apex while still employed or under contractual obligations with the Company.\n\nI further acknowledge that certain former employees intentionally delayed, misdiagnosed, or diverted active repair jobs and B2B warranty tickets (including Hisense and SquareTrade) away from the Company to artificially inflate Apex’s volume and harm the Company’s operational metrics.\n\nAll statements made in this Affidavit are true, correct, and based on my direct personal knowledge and observations. I execute this document voluntarily and without any coercion.\n\nIN WITNESS WHEREOF, I have executed this Affidavit on this ____ day of October, 2026.","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjm","name":"employee_signature","type":"signature","label":"Daven Hodge (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjn","name":"employee_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fdhmv15txbjo","name":"employee_name","type":"shortText","label":"Printed Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Daven Hodge"},{"id":"fdhmv15txbjp","name":"notary_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"NOTARY ACKNOWLEDGMENT","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjq","name":"notary_text","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>Subscribed and sworn to before me this ____ day of October, 2026.</p>","text":"Subscribed and sworn to before me this ____ day of October, 2026.","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjr","name":"notary_date","type":"datePicker","label":"Date Sworn","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjs","name":"notary_signature","type":"signature","label":"Notary Public, State of Tennessee (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbjt","name":"notary_name","type":"shortText","label":"Notary Printed Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fdhmv15txbju","name":"notary_commission_expires","type":"shortText","label":"My Commission Expires","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"}]'::jsonb, '78d3504c-56f9-43a0-b7b1-091e3eba7d36'
